package com.companages.service; import com.companages.dto.*; import com.companages.entity.*; import com.companages.exception.ResourceNotFoundException; import com.companages.repository.NotificationRepository; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.Instant;
@Service public class NotificationService {private final NotificationRepository notifications;private final CurrentUserService current;public NotificationService(NotificationRepository n,CurrentUserService c){notifications=n;current=c;}public void create(User user,Organization org,String type,String title,String message,String link){Notification n=new Notification();n.setUser(user);n.setOrganization(org);n.setType(type);n.setTitle(title);n.setMessage(message);n.setLink(link);notifications.save(n);}@Transactional(readOnly=true)public PageResponse<NotificationDtos.Response> list(Pageable p){Long id=current.get().getId();return PageResponse.from(notifications.findByUserId(id,p),this::map);}@Transactional(readOnly=true)public NotificationDtos.Summary summary(){return new NotificationDtos.Summary(notifications.countByUserIdAndReadAtIsNull(current.get().getId()));}@Transactional public void read(Long id){Notification n=notifications.findById(id).filter(x->x.getUser().getId().equals(current.get().getId())).orElseThrow(()->new ResourceNotFoundException("Notification not found"));n.setReadAt(Instant.now());}@Transactional public void readAll(){notifications.markAllRead(current.get().getId(),Instant.now());}private NotificationDtos.Response map(Notification n){return new NotificationDtos.Response(n.getId(),n.getOrganization()==null?null:n.getOrganization().getId(),n.getType(),n.getTitle(),n.getMessage(),n.getLink(),n.getReadAt()!=null,n.getCreatedAt());}}
